package io.github.wyze3306.jtb.player;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.geysermc.mcprotocollib.protocol.data.game.entity.Effect;
import org.jspecify.annotations.Nullable;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.Map;

/**
 * Bedrock mob effect network ids to Java mob effects ({@code mappings/effects/bedrock_effects.json},
 * generated by {@code tools/gen_player_mappings.py}). Bedrock-only effects map to their closest Java
 * effect ({@code fatal_poison} → poison).
 */
public final class EffectMappings {

    private static final Effect[] BY_BEDROCK_ID = load();

    private EffectMappings() {
    }

    /** The Java effect of a Bedrock effect id, or null when it has none. */
    public static @Nullable Effect toJava(int bedrockId) {
        return bedrockId >= 0 && bedrockId < BY_BEDROCK_ID.length ? BY_BEDROCK_ID[bedrockId] : null;
    }

    private static Effect[] load() {
        try (InputStream in = EffectMappings.class.getResourceAsStream("/mappings/effects/bedrock_effects.json")) {
            if (in == null) {
                throw new IllegalStateException("Missing mappings/effects/bedrock_effects.json");
            }
            JsonObject json = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            int max = 0;
            for (String key : json.keySet()) {
                max = Math.max(max, Integer.parseInt(key));
            }
            Effect[] effects = new Effect[max + 1];
            for (Map.Entry<String, JsonElement> entry : json.entrySet()) {
                String javaKey = entry.getValue().getAsString();
                String path = javaKey.substring(javaKey.indexOf(':') + 1);
                effects[Integer.parseInt(entry.getKey())] = Effect.valueOf(path.toUpperCase(Locale.ROOT));
            }
            return effects;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
